using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Runtime.Serialization.Json;using System.Threading;
namespace Frociart.Tests {internal static class DirectManipulationTests {
 static int checks;static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static string folder;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static object Call(object o,string n,params object[] args){var m=o.GetType().GetMethods(F).First(x=>x.Name==n&&x.GetParameters().Length==args.Length);return m.Invoke(o,args);}
 static T Get<T>(object o,string n){return (T)o.GetType().GetField(n,F).GetValue(o);}
 static void Pump(int ms=0){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(5);}while(DateTime.UtcNow<end);}
 static string Bytes(Diagram d){using(var m=new MemoryStream()){new DataContractJsonSerializer(typeof(Diagram)).WriteObject(m,d);return Convert.ToBase64String(m.ToArray());}}
 static Diagram Fixture(){var d=new Diagram{Title="Gesti diretti"};d.Nodes.AddRange(new[]{new FlowNode{Id="s",Kind=NodeKind.Start,X=100,Y=20,Text="Inizio"},new FlowNode{Id="m",Kind=NodeKind.Process,X=76,Y=220,Text="x = 1"},new FlowNode{Id="e",Kind=NodeKind.End,X=100,Y=530,Text="Fine"},new FlowNode{Id="far",Kind=NodeKind.Output,X=1100,Y=180,Text="x"}});d.Edges.AddRange(new[]{new FlowEdge{Id="in",From="s",To="m"},new FlowEdge{Id="out",From="m",To="e"}});return d;}
 static Point At(FlowCanvas c,float x,float y){return Point.Round(c.WorldToClient(new PointF(x,y)));}
 static void Mouse(FlowCanvas c,string n,Point p){Call(c,n,new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Pump();}
 static void Shot(FlowCanvas c,string name){using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,c.ClientRectangle);b.Save(Path.Combine(folder,name+".png"));}}
 static void Reset(MainForm form){form.SetDocument(Fixture(),null,false);form.Canvas.SnapToGrid=false;form.Canvas.FitToView();Pump();}
 static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(var next in Walk(child))yield return next;}
 static void Answer(MainForm form,string title,string label,Action action){Exception error=null;bool seen=false;using(var timer=new System.Windows.Forms.Timer{Interval=20}){timer.Tick+=delegate{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f!=form&&f.Text.StartsWith(title));if(dialog==null)return;timer.Stop();try{seen=true;((Button)Walk(dialog).First(c=>c is Button&&(c.Text==label||label=="Annulla"&&c.Text=="Annulla inserimento"))).PerformClick();}catch(Exception ex){error=ex;dialog.DialogResult=DialogResult.Cancel;dialog.Close();}};timer.Start();action();}if(error!=null)throw error;Check(seen,"Native choice shown: "+title+" -> "+label);}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);folder=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"direct");Directory.CreateDirectory(folder);
 using(var form=new MainForm(null,true)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-3000,-2500);form.Size=new Size(1420,1000);form.Show();form.EnterEditor();Pump();
 foreach(NodeKind kind in new[]{NodeKind.Input,NodeKind.Process,NodeKind.Output}){Reset(form);var c=form.Canvas;string before=Bytes(form.Document);var data=new DataObject(new FlowCanvas.PaletteBlock(kind));Point p=At(c,182,440),screen=c.PointToScreen(p);var ev=new DragEventArgs(data,1,screen.X,screen.Y,DragDropEffects.Copy,DragDropEffects.None);Call(c,"OnDragEnter",ev);Pump(90);float early=Get<float>(c,"paletteReveal");Check(ev.Effect==DragDropEffects.Copy&&form.Document.Nodes.Count==4,"Native palette DragEnter accepts without creating a node");Check(Get<bool>(c,"insertReady"),"Menu block offers insertion directly on the line");Shot(c,"01-palette-"+kind);Pump(130);Check(early>=0&&early<1.1f&&Math.Abs(Get<float>(c,"paletteReveal")-1)<.15f,"Ghost spring approaches its resting scale without an invalid overshoot");Call(c,"OnDragDrop",ev);Pump();Check(form.Document.Nodes.Count==5&&form.Document.Edges.Count==3,"One native menu drop creates and splices the new block");Check(Get<System.Collections.ICollection>(form,"undo").Count==1,"Creation and local layout share one Undo");Check(form.Document.Nodes.First(x=>x.Id=="far").X==1100&&form.Document.Nodes.First(x=>x.Id=="far").Y==180,"Distant region remains exactly fixed");Shot(c,"02-created-"+kind);Call(form,"Undo");Pump();Check(Bytes(form.Document)==before,"Undo removes the created block and all local shifts");}
 Reset(form);var canvas=form.Canvas;string original=Bytes(form.Document);Point center=At(canvas,182,264);Mouse(canvas,"OnMouseDown",center);Pump(600);Check(Get<float>(canvas,"holdFill")==0&&!Get<bool>(canvas,"stickerDetached"),"A short stationary press has no fill or detach");Pump(450);Check(Get<float>(canvas,"holdFill")>.15f&&Get<float>(canvas,"holdFill")<1,"Hold visibly fills before detachment");Shot(canvas,"03-hold-fill");Pump(800);Check(Get<bool>(canvas,"stickerDetached")&&Get<float>(canvas,"lift")>.8f,"Hold completion animates the sticker lift");Check(form.Document.Edges[0].To=="m"&&Get<System.Collections.ICollection>(form,"undo").Count==0,"Peel and bypass remain preview until release");Shot(canvas,"04-sticker-lift");var blank=At(canvas,650,280);Mouse(canvas,"OnMouseMove",blank);Mouse(canvas,"OnMouseUp",blank);Check(form.Document.Edges.Count==1&&form.Document.Edges[0].To=="e"&&!form.Document.Edges.Any(x=>x.From=="m"||x.To=="m"),"Sticker release reconnects neighbours and leaves the block detached");Check(Get<System.Collections.ICollection>(form,"undo").Count==1,"Detachment and movement make one history entry");Check(Get<Label>(form,"status").Text.Contains("ricucito"),"Released sticker feedback describes the actual reconnection");Call(form,"Undo");Pump();Check(Bytes(form.Document)==original,"One Undo restores the attached block and exact coordinates");
 Reset(form);Mouse(canvas,"OnMouseDown",At(canvas,182,264));Pump(1950);Call(canvas,"OnKeyDown",new KeyEventArgs(Keys.Escape));Pump();Check(Bytes(form.Document)==original&&Get<System.Collections.ICollection>(form,"undo").Count==0,"Escape during the peel restores the original without history");
 Reset(form);canvas.BeginPalettePreview(NodeKind.Process,At(canvas,650,280));canvas.EndPalettePreview();Check(Bytes(form.Document)==original&&Get<System.Collections.ICollection>(form,"undo").Count==0,"Leaving or cancelling a palette drag creates nothing");
 Reset(form);original=Bytes(form.Document);canvas.BeginPalettePreview(NodeKind.Decision,At(canvas,182,440));Answer(form,"Inserisci la decisione","No",()=>Call(canvas,"CommitPaletteDrop"));Check(form.Document.Nodes.Count==5&&form.Document.Nodes.Any(n=>n.Kind==NodeKind.Decision&&form.Document.Edges.Any(e=>e.From==n.Id&&e.Branch=="false"&&e.To=="e")),"A palette decision is created only after the native No choice");Call(form,"Undo");Pump();Check(Bytes(form.Document)==original,"Undo removes the palette decision and its local placement");
 canvas.BeginPalettePreview(NodeKind.Decision,At(canvas,182,440));Answer(form,"Inserisci la decisione","Annulla",()=>Call(canvas,"CommitPaletteDrop"));Check(Bytes(form.Document)==original&&Get<System.Collections.ICollection>(form,"undo").Count==0,"Cancelling a palette decision creates no block and no history");
 Reset(form);original=Bytes(form.Document);canvas.BeginPalettePreview(NodeKind.Decision,At(canvas,182,440));Answer(form,"Inserisci la decisione","Nessuno",()=>Call(canvas,"CommitPaletteDrop"));var noneDecision=form.Document.Nodes.FirstOrDefault(n=>n.Kind==NodeKind.Decision);Check(noneDecision!=null&&form.Document.Edges.Any(e=>e.To==noneDecision.Id)&&!form.Document.Edges.Any(e=>e.From==noneDecision.Id),"None inserts the decision with two free exits");Check(form.Document.Nodes.Any(n=>n.Id=="e")&&Get<System.Collections.ICollection>(form,"undo").Count==1,"None preserves the previous target and has one Undo");Call(form,"Undo");Pump();Check(Bytes(form.Document)==original,"Undo of None restores the original full graph");
 Reset(form);original=Bytes(form.Document);Mouse(canvas,"OnMouseDown",At(canvas,182,264));Pump(1950);Mouse(canvas,"OnMouseMove",At(canvas,182,430));Check(Get<bool>(canvas,"insertReady"),"Lifted block can target the newly bypassed old line");Mouse(canvas,"OnMouseUp",At(canvas,182,430));Check(form.Document.Edges.Count==2&&form.Document.Edges.First(e=>e.Id=="in").To=="m"&&form.Document.Edges.Any(e=>e.From=="m"&&e.To=="e"),"Sticker can be reinserted into its bypassed line");Check(Get<float>(canvas,"landingLift")>0,"Release starts an animated landing");canvas.ExportPng(Path.Combine(folder,"during-landing.png"));Pump(440);canvas.ExportPng(Path.Combine(folder,"after-landing.png"));Check(File.ReadAllBytes(Path.Combine(folder,"during-landing.png")).SequenceEqual(File.ReadAllBytes(Path.Combine(folder,"after-landing.png"))),"Landing and local layout never enter exported PNG data");Call(form,"Undo");Pump();Check(Bytes(form.Document)==original,"Reinsertion into the bypassed line still has one complete Undo");
 foreach(int mode in new[]{0,1,2}){
  var branchedMove=Examples.Parity();if(mode==1)foreach(var e in branchedMove.Edges.Where(x=>x.From=="check"))e.To="even";if(mode==2)branchedMove.Edges.RemoveAll(x=>x.From=="check"&&x.Branch=="false");
  form.SetDocument(branchedMove,null,false);canvas.SnapToGrid=false;canvas.FitToView();Pump();original=Bytes(form.Document);var decision=form.Document.Nodes.First(n=>n.Id=="check");var db=FlowCanvas.GetNodeBounds(decision);var links=form.Document.Edges.Select(e=>e.Id+e.From+e.To+e.Branch).ToArray();
  Mouse(canvas,"OnMouseDown",At(canvas,db.Left+db.Width/2,db.Top+db.Height/2));Pump(1950);Check(Get<float>(canvas,"lift")>.9&&form.Document.Edges.Select(e=>e.Id+e.From+e.To+e.Branch).SequenceEqual(links),"Decision peel preserves the original graph until release: "+mode);
  var free=At(canvas,1200,-200);Mouse(canvas,"OnMouseMove",free);Mouse(canvas,"OnMouseUp",free);Check(!form.Document.Edges.Any(e=>e.From=="check"||e.To=="check")&&form.Document.Nodes.Count==branchedMove.Nodes.Count,"Completed decision peel detaches while preserving every block: "+mode);Check(Get<System.Collections.ICollection>(form,"undo").Count==1,"Decision movement has one Undo: "+mode);Call(form,"Undo");Pump();Check(Bytes(form.Document)==original,"Decision Undo restores all fields: "+mode);
 }
 Reset(form);original=Bytes(form.Document);Mouse(canvas,"OnMouseDown",At(canvas,182,264));Mouse(canvas,"OnMouseMove",At(canvas,650,280));Pump(1900);Check(Get<float>(canvas,"holdFill")==0&&Get<long>(canvas,"holdStart")<0&&!Get<bool>(canvas,"stickerDetached"),"Dragging before the hold threshold cancels the entire sticker sequence");Mouse(canvas,"OnMouseUp",At(canvas,650,280));Check(form.Document.Edges.Count==2&&form.Document.Edges[0].To=="m","Long ordinary drag keeps original connections");Call(form,"Undo");Pump();Check(Bytes(form.Document)==original,"Ordinary drag remains one complete Undo");
 Reset(form);Mouse(canvas,"OnMouseDown",At(canvas,182,264));Pump(1250);Mouse(canvas,"OnMouseMove",At(canvas,650,280));Pump(900);Check(Get<float>(canvas,"holdFill")==0&&!Get<bool>(canvas,"stickerDetached"),"Moving during filling cancels the pending peel");Mouse(canvas,"OnMouseUp",At(canvas,650,280));Call(form,"Undo");
 var collision=Fixture();collision.Nodes.First(x=>x.Id=="m").X=100;collision.Nodes.First(x=>x.Id=="m").Y=500;FlowPlacement.Reflow(collision,"m","s","e",true);Check(FlowCanvas.GetNodeBounds(collision.Nodes[1]).Bottom+50<=collision.Nodes[2].Y,"Local placement opens a readable gap after the inserted block");Check(collision.Nodes[3].X==1100&&collision.Nodes[3].Y==180,"Local reflow leaves an unrelated region unchanged");
 var branched=Examples.Parity();string encoded=Bytes(branched);Check(!FlowPlacement.Detach(branched,"check")&&Bytes(branched)==encoded,"Two distinct decision branches are never guessed during detachment");Check(FlowPlacement.DetachVia(branched,"check","false")&&!branched.Edges.Any(x=>x.From=="check")&&branched.Edges.Any(x=>x.To=="odd"),"Explicit No choice reconnects the previous location correctly");
 form.SetDocument(new Diagram(),null,false);form.Close();}Console.WriteLine("DIRECT_MANIPULATION_FINISHED checks="+checks+" errors=0");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}}
